parameters.jsCode:
// n8n Code node (JavaScript)
// Output por item:
// - mensaje_real: string (lo que se envía al usuario)
// - razonamiento: string (bloque(s) [Used tools: ...] si existen)
// - mensaje_original: string (input original)
// - tenia_razonamiento: boolean

function tryParseJsonString(s) {
  if (typeof s !== 'string') return null;
  const t = s.trim();
  if (!t) return null;

  // Solo intentamos parsear si "parece" JSON
  const looksJson =
    (t.startsWith('[') && t.endsWith(']')) ||
    (t.startsWith('{') && t.endsWith('}'));

  if (!looksJson) return null;

  try {
    return JSON.parse(t);
  } catch {
    return null;
  }
}

function normalizeContentFromItemJson(itemJson) {
  // 1) Caso típico: { content: "..." }
  if (itemJson && typeof itemJson === 'object' && !Array.isArray(itemJson)) {
    if (typeof itemJson.content === 'string') {
      // Puede ser texto normal o un JSON-string tipo '[{"content":"..."}]'
      const parsed = tryParseJsonString(itemJson.content);
      if (Array.isArray(parsed) && parsed[0] && typeof parsed[0].content === 'string') {
        return parsed[0].content;
      }
      if (parsed && typeof parsed === 'object' && typeof parsed.content === 'string') {
        return parsed.content;
      }
      return itemJson.content;
    }

    // Fallbacks comunes
    if (typeof itemJson.message === 'string') return itemJson.message;
    if (typeof itemJson.text === 'string') return itemJson.text;
  }

  // 2) Si el json ENTERO es un string JSON
  if (typeof itemJson === 'string') {
    const parsed = tryParseJsonString(itemJson);
    if (Array.isArray(parsed) && parsed[0] && typeof parsed[0].content === 'string') {
      return parsed[0].content;
    }
    if (parsed && typeof parsed === 'object' && typeof parsed.content === 'string') {
      return parsed.content;
    }
    return itemJson;
  }

  // 3) Si el json ENTERO es un array tipo [{content:"..."}]
  if (Array.isArray(itemJson)) {
    const first = itemJson.find(x => x && typeof x.content === 'string');
    if (first) return first.content;
    return JSON.stringify(itemJson);
  }

  // 4) Último recurso
  return itemJson == null ? '' : String(itemJson);
}

function stripUsedToolsBlocks(text) {
  if (typeof text !== 'string') {
    return { mensaje: '', razonamiento: '' };
  }

  let rest = text.replace(/^\s+/, ''); // trimStart
  const blocks = [];

  // Evita loops infinitos ante strings raros
  const maxLoops = 10;

  for (let loop = 0; loop < maxLoops; loop++) {
    if (!rest.startsWith('[')) break;

    // Solo lo tratamos como "razonamiento" si realmente dice "Used tools"
    // (así no rompemos mensajes que empiezan con "[" por otros motivos)
    const head = rest.slice(0, 80).toLowerCase();
    if (!head.match(/^\[\s*used tools?\b/)) break;

    // Encontrar el ']' que cierra el primer '[' del inicio,
    // contando corchetes y respetando strings con escapes.
    let depth = 0;
    let inString = false;
    let quote = '';
    let escaped = false;
    let endIdx = -1;

    for (let i = 0; i < rest.length; i++) {
      const ch = rest[i];

      if (inString) {
        if (escaped) {
          escaped = false;
          continue;
        }
        if (ch === '\\') {
          escaped = true;
          continue;
        }
        if (ch === quote) {
          inString = false;
          quote = '';
        }
        continue;
      }

      // fuera de string
      if (ch === '"' || ch === "'") {
        inString = true;
        quote = ch;
        continue;
      }

      if (ch === '[') depth++;
      else if (ch === ']') {
        depth--;
        if (depth === 0) {
          endIdx = i;
          break;
        }
      }
    }

    // Si no pudimos cerrar el bloque, no tocamos nada (fail-safe)
    if (endIdx === -1) break;

    blocks.push(rest.slice(0, endIdx + 1));
    rest = rest.slice(endIdx + 1).replace(/^\s+/, ''); // trimStart
  }

  // Fail-safe: si por algún motivo quedó vacío, devolvemos el original
  const mensajeFinal = rest.length ? rest : text;

  return {
    mensaje: mensajeFinal,
    razonamiento: blocks.join('\n\n'),
  };
}

const items = $input.all();

return items.map((item) => {
  const original = normalizeContentFromItemJson(item.json);
  const { mensaje, razonamiento } = stripUsedToolsBlocks(original);

  return {
    json: {
      ...item.json,
      mensaje_real: mensaje,
      razonamiento,
      mensaje_original: original,
      tenia_razonamiento: Boolean(razonamiento),
    }
  };
});
